        be exceeded, dropping one shift elsewhere. Kept only if the summed cost over all queues falls."""
        for _ in range(rounds):
            gaps = self.total_cost()[0]
            if not gaps:
                return
            improved = False
            for q in self.queues:
                brk, _ = self.breaks(q)
                net = list(self.gross[q])
                for i in brk.values():
                    net[i] -= 1
                gap_days = sorted({self.grid[i].astimezone(self.z).date()
                                   for i, f in enumerate(self.floor[q]) if f and net[i] < f})
                for day in gap_days:
                    if self.try_floor_day(q, day):
                        improved = True
            if not improved:
                return

    def try_floor_day(self, q: str, day: date) -> bool:
        cur = self.total_cost()
        di = self.days.index(day)
        nbrs = [self.days[k] for k in (di - 1, di + 1) if 0 <= k < len(self.days)]
        best, best_cost = None, cur
        for a in self.holders(q):
            aid = a.agent_id
            here = self.plan.get((aid, day))
            saved = {d: self.plan.get((aid, d)) for d in nbrs}
            nbr_opts = []
            for d in nbrs:
                h = saved[d]
                opts = [h, None] + ([(t.id, h[1]) for t in self.templates if t.id != h[0]] if h else [])
                nbr_opts.append(opts)
            for tpl in self.templates:
                new = (tpl.id, q)
                if new == here:
                    continue
                for combo in itertools.product(*nbr_opts):
                    self.set(aid, day, None)
                    ok = True
                    for d, o in zip(nbrs, combo):
                        if o != saved[d]:
                            self.set(aid, d, None)
                    for d, o in zip(nbrs, combo):
                        if o and o != saved[d]:
                            if not self.can_take(aid, d, o[0], o[1]):
                                ok = False
                                break
                            self.set(aid, d, o)
                    if ok and self.can_take(aid, day, tpl.id, q):
                        self.set(aid, day, new)
                        if self.total_hours <= self.hours_budget + 1e-9:
                            c = self.total_cost()
                            if c < best_cost:
                                best, best_cost = (aid, day, new, dict(zip(nbrs, combo)), None), c
                        else:
                            drop = self.cheapest_drop(exclude={(aid, day)} | {(aid, d) for d in nbrs})
                            if drop:
                                key, val = drop
                                self.set(*key, None)
                                c = self.total_cost()
                                if c < best_cost:
                                    best, best_cost = (aid, day, new, dict(zip(nbrs, combo)), key), c
                                self.set(*key, val)
                    # restore
                    self.set(aid, day, None)
                    for d in nbrs:
                        self.set(aid, d, None)
                    for d in nbrs:
                        if saved[d]:
                            self.set(aid, d, saved[d])
                    if here:
                        self.set(aid, day, here)
        if best is None:
            return False
        aid, day, new, nb, drop = best
        self.set(aid, day, None)
        for d in nb:
            self.set(aid, d, None)
        for d, o in nb.items():
            if o:
                self.set(aid, d, o)
        self.set(aid, day, new)
        if drop:
            self.set(*drop, None)
        return True

    def cheapest_drop(self, exclude: set) -> tuple | None:
        """The agent-day whose removal raises the summed cost least (never one that opens a floor gap)."""
        base = self.total_cost()
        best, best_key = None, None
        for key, val in list(self.plan.items()):
            if key in exclude:
                continue
            self.set(*key, None)
            c = self.total_cost()
            self.set(*key, val)
            if c[0] > base[0]:
                continue
            k = (c, -self.shape[(val[0], key[1])][3])
            if best_key is None or k < best_key:
                best, best_key = (key, val), k
        return best

